def first_divergence(n, honest, claimed):
    """honest(i) and claimed(i) give the state after i steps, for 0 <= i <= n.
    They agree at 0 and disagree at n. Return an index i with honest(i) == claimed(i)
    and honest(i + 1) != claimed(i + 1), asking `claimed` for only O(log n) states."""
    for i in range(n):
        if honest(i + 1) != claimed(i + 1):
            return i

